@Serializable
data class Session(val startedAt: Instant, val day: LocalDate)

fun newSession(zone: TimeZone = TimeZone.currentSystemDefault()): Session {
  val now = Clock.System.now()                  // not System.currentTimeMillis()
  return Session(startedAt = now, day = now.toLocalDateTime(zone).date)
}

// Duration comes from a monotonic source: a clock correction between two
// Clock.System.now() calls can hand you a negative elapsed time.
val mark = TimeSource.Monotonic.markNow()
fun sinceStart() = mark.elapsedNow()            // kotlin.time.Duration

