// commonMain — one Json, one place where transport failures become domain errors
val appJson = Json {
  ignoreUnknownKeys = true       // the backend will add fields
  explicitNulls = false
}

sealed class ApiError : Exception() {
  data object Unauthorized : ApiError()
  data class Http(val status: Int) : ApiError()
  data object BadPayload : ApiError()
  data class Network(val reason: Throwable) : ApiError()
}

fun api(engineClient: HttpClient): HttpClient = engineClient.config {
  expectSuccess = true           // default is false: a 502 is otherwise "just a response"
  install(ContentNegotiation) { json(appJson) }

  HttpResponseValidator {
    handleResponseExceptionWithRequest { cause, _ ->
      throw when (cause) {
        is ClientRequestException ->
          if (cause.response.status == HttpStatusCode.Unauthorized) ApiError.Unauthorized
          else ApiError.Http(cause.response.status.value)
        is ServerResponseException -> ApiError.Http(cause.response.status.value)
        is JsonConvertException, is NoTransformationFoundException -> ApiError.BadPayload
        else -> ApiError.Network(cause)
      }
    }
  }
}

// The gateway's text/html 502 reaches body<User>() and dies as
// NoTransformationFoundException: no status, no url, nothing the UI can show.
// suspend fun user(id: Long): User = raw.get("$base/users/$id").body()

// Status is decided first, so body<T>() only ever sees a 2xx JSON payload
suspend fun user(id: Long): User =
  client.get("$base/users/$id") { accept(ContentType.Application.Json) }.body()

suspend fun save(u: User): Unit =
  client.post("$base/users") {
    contentType(ContentType.Application.Json)   // without this the body is not encoded
    setBody(u)
  }.body()

// Closed polymorphism: sealed + @Serializable, subclasses registered by the plugin
@Serializable
@JsonClassDiscriminator("kind")        // the default key is "type"
sealed interface FeedItem {
  @Serializable @SerialName("post")   data class Post(val id: Long, val body: String) : FeedItem
  @Serializable @SerialName("ad")     data class Ad(val id: Long, val campaign: String) : FeedItem
  @Serializable @SerialName("banner") data class Banner(val id: Long, val image: String) : FeedItem
}

val appJson = Json { ignoreUnknownKeys = true }
fun feed(raw: String): List<FeedItem> = appJson.decodeFromString(raw)

// Without @SerialName the discriminator is com.example.feed.Post, so moving the
// class or letting R8 rename it changes the payload without changing any code.

// A property literally called "kind" collides with the discriminator and Json
// refuses the hierarchy on first use. Rename one of the two.

// Open polymorphism: a non-sealed base is registered by hand. Nothing scans the
// classpath, and Kotlin/Native has no Class.forName to fall back on.
val attachments = SerializersModule {
  polymorphic(Attachment::class) {
    subclass(ImageAttachment::class)
    subclass(FileAttachment::class)
    defaultDeserializer { UnknownAttachment.serializer() }   // survives a new server type
  }
}
val tolerant = Json { serializersModule = attachments; ignoreUnknownKeys = true }

// No discriminator on the wire at all? Choose the serializer from the shape.
object ItemSerializer : JsonContentPolymorphicSerializer<FeedItem>(FeedItem::class) {
  override fun selectDeserializer(element: JsonElement) = when {
    "campaign" in element.jsonObject -> FeedItem.Ad.serializer()
    "image" in element.jsonObject -> FeedItem.Banner.serializer()
    else -> FeedItem.Post.serializer()
  }
}

