class PlayerRepo(
  private val db: AppDatabase,
  private val io: CoroutineDispatcher = Dispatchers.IO,
) {
  // Generated calls block. On the main thread this is the frame you dropped.
  // fun all(): List<Player> = db.playerQueries.selectAll().executeAsList()

  suspend fun all(): List<Player> = withContext(io) {
    db.playerQueries.selectAll().executeAsList()
  }

  suspend fun replace(players: List<Player>) = withContext(io) {
    db.transaction {                       // short: SQLite serialises writers
      db.playerQueries.deleteAll()
      players.forEach { db.playerQueries.insert(it.id, it.name) }
    }
  }
}

