class PlayerRepo(
  private val db: AppDatabase,
  private val driver: SqlDriver,
  private val io: CoroutineDispatcher = Dispatchers.IO,
) {
  // asFlow() emits Query objects; mapToList runs them on the context you hand it.
  // Dispatchers.Main there would execute SQL on the UI thread.
  fun observe(): Flow<List<Player>> =
    db.playerQueries.selectAll()
      .asFlow()
      .mapToList(io)
      .distinctUntilChanged()      // notification is per table, not per row

  // One emission, not twenty: notifications are deferred to the outermost commit
  suspend fun replaceAll(players: List<Player>) = withContext(io) {
    db.transaction {
      db.playerQueries.deleteAll()
      players.forEach { db.playerQueries.insert(it.id, it.name) }
    }
  }

  // Nothing tells the listener registry which tables this touched, so observe()
  // never fires and the screen looks frozen until it is recreated.
  suspend fun renameRaw(id: Long, name: String) = withContext(io) {
    driver.execute(null, "UPDATE player SET name = ? WHERE id = ?", 2) {
      bindString(0, name)
      bindLong(1, id)
    }
  }

  // The generated mutator notifies every query that reads `player`
  suspend fun rename(id: Long, name: String) = withContext(io) {
    db.playerQueries.updateName(name = name, id = id)
  }
}

