// iosMain — the accessibility class is the part no common API can express
@OptIn(ExperimentalForeignApi::class)
class KeychainTokenStore : TokenStore {

  override suspend fun write(token: String) {
    val query = mapOf<Any?, Any?>(
      kSecClass to kSecClassGenericPassword,
      kSecAttrAccount to "auth_token",
      kSecAttrAccessible to kSecAttrAccessibleAfterFirstUnlockThisDeviceOnly,
      kSecValueData to token.toNSData()
    )
    SecItemDelete(query as CFDictionaryRef)   // Keychain items survive reinstall
    SecItemAdd(query as CFDictionaryRef, null)
  }

  override suspend fun read(): String? = memScoped { readItem("auth_token") }
  override suspend fun clear() { SecItemDelete(deleteQuery("auth_token")) }
}

// commonTest — possible only because it is an interface
class InMemoryTokenStore : TokenStore {
  private var value: String? = null
  override suspend fun read() = value
  override suspend fun write(token: String) { value = token }
  override suspend fun clear() { value = null }
