// commonMain
class FeedRepository(private val client: HttpClient, private val baseDelayMs: Long = 500) {

  suspend fun load(attempts: Int = 3): List<Post> {
    repeat(attempts - 1) { i ->
      runCatching { client.get("/feed").body<List<Post>>() }.onSuccess { return it }
      delay(baseDelayMs shl i)          // our own delay: the test scheduler owns it
    }
    return client.get("/feed").body()
  }
}

// commonTest
class FeedRepositoryRetryTest {

  @Test
  fun retriesTwiceThenSucceeds() = runTest {
    var calls = 0
    val engine = MockEngine { _ ->
      calls++
      if (calls < 3) respondError(HttpStatusCode.ServiceUnavailable)
      else respond(
        content = """[{"id":1,"title":"hi"}]""",
        status = HttpStatusCode.OK,
        // without this header ContentNegotiation never sees JSON
        headers = headersOf(HttpHeaders.ContentType, "application/json")
      )
    }
    val client = HttpClient(engine) {
      expectSuccess = true
      install(ContentNegotiation) { json() }
    }

    val posts = FeedRepository(client, baseDelayMs = 100).load()

    assertEquals(1, posts.size)
    assertEquals(3, calls)
    assertEquals(300, testScheduler.currentTime)   // 100 + 200, skipped in virtual time
    client.close()
  }
}

// commonMain
interface CrashReporter {
  fun log(message: String)
  fun setKey(key: String, value: String)
  fun record(error: Throwable)          // non-fatal
}

// iosMain — the Kotlin exception must be reported before the runtime tears the app down
fun installKotlinCrashHook(reporter: CrashReporter) {
  setUnhandledExceptionHook { throwable ->
    reporter.setKey("kotlin_exception", throwable::class.simpleName ?: "unknown")
    reporter.log(throwable.stackTraceToString().take(2048))
    reporter.record(throwable)
    terminateWithUnhandledException(throwable)   // still crash, now with context attached
  }
}

// androidMain — the JVM already has a readable trace; keep the same interface
class CrashlyticsReporter : CrashReporter {
  private val crashlytics = FirebaseCrashlytics.getInstance()
  override fun log(message: String) = crashlytics.log(message)
  override fun setKey(key: String, value: String) = crashlytics.setCustomKey(key, value)
  override fun record(error: Throwable) = crashlytics.recordException(error)
}

